// Un seul point de vérité pour le repo cible — c'est ce node qui rend `repo`
// extensible sans retoucher la structure du workflow (cf. plan Symphony Phase 2).
// MVP : une seule entrée. Ajouter une ligne ici (et une valeur de label Linear
// correspondante, ex. repo:autre-app) suffira pour un futur repo additionnel.
const REPO_MAP = {
  'agent-infra': { owner: 'Exawyll', repo: 'agent-infra', workflowFile: 'symphony-run-dev.yml' }
};

return [{ json: { repoMap: REPO_MAP, targetRepoLabel: 'repo:agent-infra' } }];

// Les 4 critères d'éligibilité SPEC.md : label agent:ok (déjà filtré côté GraphQL),
// type renseigné, repo sans ambiguïté, critères d'acceptation non vides.
// Un ticket qui échoue est ignoré silencieusement (pas une erreur, cf. plan Phase 2).
// Défaut = labels réels du board agent-infra (vérifiés en direct via l'API Linear) :
// bug/evolution/docs, en minuscules — pas Bug/Feature/Improvement.
const TYPE_LABELS = (($env.LINEAR_TYPE_LABELS) || 'bug,evolution,docs').split(',').map(s => s.trim());

const resp = $input.first().json;
const issues = (resp.data && resp.data.issues && resp.data.issues.nodes) || [];

const eligible = issues
  .map((issue) => {
    const labelNames = (issue.labels && issue.labels.nodes || []).map((l) => l.name);
    const repoLabel = labelNames.find((n) => n.startsWith('repo:'));
    const hasType = labelNames.some((n) => TYPE_LABELS.includes(n));
    const hasCriteria = !!(issue.description && issue.description.trim().length > 0);
    const repoOk = repoLabel === 'repo:agent-infra'; // MVP : une seule valeur valide
    return {
      ...issue,
      _eligible: hasType && hasCriteria && repoOk,
      _repo: repoLabel ? repoLabel.slice('repo:'.length) : null
    };
  })
  .filter((i) => i._eligible)
  .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));

return eligible.map((issue) => ({ json: issue }));

// Fusionne le résultat des deux requêtes précédentes (In Progress + éligibles)
// et n'autorise le passage que si aucun ticket repo:agent-infra n'est déjà In Progress.
const inProgressResp = $('Linear: query In Progress (repo)').first().json;
const inProgressCount = (inProgressResp.data && inProgressResp.data.issues && inProgressResp.data.issues.nodes || []).length;

const eligible = $input.all().map((i) => i.json);

if (inProgressCount > 0 || eligible.length === 0) {
  return []; // rien à faire ce tour-ci
}

// Le plus ancien ticket éligible uniquement — un seul run à la fois.
return [{ json: eligible[0] }];

// Jamais d'ID Linear (state ou label) en dur dans ce repo — résolus par nom à
// chaque run via l'API, pour absorber le mapping réel du board (cf. Prérequis
// #1 du plan Symphony Phase 2 : les states réels peuvent ne pas s'appeler
// littéralement "Ready"/"In Progress").
const ticket = $('Concurrence: 1 run/repo').first().json;
const resolved = $input.first().json;
const states = (resolved.data && resolved.data.team && resolved.data.team.states.nodes) || [];
const labels = (resolved.data && resolved.data.team && resolved.data.team.labels.nodes) || [];

const wantedState = $env.LINEAR_STATE_IN_PROGRESS || 'In Progress';
const targetState = states.find((s) => s.name === wantedState);
if (!targetState) {
  throw new Error(`State "${wantedState}" introuvable sur l'équipe Linear — vérifier LINEAR_STATE_IN_PROGRESS / le board réel.`);
}

const attemptLabel = labels.find((l) => l.name === 'attempt:1');
if (!attemptLabel) {
  throw new Error('Label "attempt:1" introuvable — le créer sur le board Linear (cf. Prérequis Phase 2) avant le premier run.');
}

return [{ json: { ticket, targetStateId: targetState.id, attemptLabelId: attemptLabel.id } }];

// Pas de staticData n8n ici : un workflow n'a pas accès au staticData d'un autre
// (dispatcher/watchdog/merge-handler sont 3 workflows distincts). L'état partagé
// entre-eux vit donc dans Linear lui-même : `startedAt` est déjà natif sur l'API
// Linear (rempli automatiquement à l'entrée dans un state de type "started"),
// et le compteur de tentative/rejet est porté par des labels `attempt:N` /
// `rejected:N` — visibles dans l'UI Linear, lisibles par n'importe quel workflow.
const prev = $('Construire mutation In Progress').first().json;
return [{ json: { ticket: prev.ticket, attempt: 1, attemptLabelId: prev.attemptLabelId } }];
